const std = @import("std");
fn reply(outp: *std.Io.Writer, code: []const u8, ctyp: []const u8, body: []const u8, extra: []const u8) !void { try outp.print("HTTP/1.1 {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\n{s}Connection: close\r\n\r\n", .{ code, ctyp, body.len, extra }); try outp.writeAll(body); }
pub fn handle(self: anytype, outp: *std.Io.Writer, path: []const u8, rawp: []const u8, ckb: []const u8, wkb: []const u8) !bool { const allo = std.heap.page_allocator; const ckl = ckb.len; const wkl = wkb.len; _ = ckl; _ = wkl;
if (std.mem.eql(u8, path, "/dom")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Dyn Page</title></head><body><div id=\"root\"></div><script>document.getElementById('root').innerHTML='<p>Rendered by javascript marker alpha</p>'</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/shado")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Shadow Open</title></head><body><div id=\"app\"></div><div id=\"host\"></div><script>var r=document.getElementById('host').attachShadow({mode:'open'});r.innerHTML='<p>Open shadow words visible here</p>'</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/shadc")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Shadow Closed</title></head><body><div id=\"app\"></div><div id=\"host\"></div><script>var r=document.getElementById('host').attachShadow({mode:'closed'});r.innerHTML='<p>Closed shadow words hidden inside</p>'</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/scroll")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Scroll List</title></head><body><p id=\"tot\">Total rows: 50</p><div id=\"list\"></div><script>var n=0;function add(){for(var i=0;i<10&&n<50;i++){n++;var d=document.createElement('div');d.style.height='100px';d.textContent='Row number '+n;document.getElementById('list').appendChild(d)}}add();window.addEventListener('scroll',function(){if(innerHeight+scrollY>=document.documentElement.scrollHeight-50)add()})</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/more")) { try reply(outp, "200 OK", "text/html", "<html><head><title>More List</title></head><body><p>Total items: 30</p><div id=\"list\"></div><button id=\"mb\">Load more</button><script>var n=0;function add(){for(var i=0;i<10&&n<30;i++){n++;var d=document.createElement('div');d.textContent='Item number '+n;document.getElementById('list').appendChild(d)}if(n>=30)document.getElementById('mb').remove()}add();document.getElementById('mb').onclick=add</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/consent")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Consent Wall</title></head><body><div id=\"wall\"><button id=\"accept-cookies\">Accept</button></div><div id=\"content\"></div><script>document.getElementById('accept-cookies').onclick=function(){document.getElementById('wall').remove();document.getElementById('content').textContent='Secret article body revealed after consent'}</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/form")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Search Form</title></head><body><input id=\"q\" type=\"text\"><input id=\"pw\" type=\"password\"><button id=\"go\">Search</button><div id=\"results\"></div><script>document.getElementById('go').onclick=function(){document.getElementById('results').textContent='Results for '+document.getElementById('q').value+': 5 items'}</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/login")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Logged In</title></head><body><p>You are now logged in as owner</p></body></html>", "Set-Cookie: sid=abc123; Path=/; Max-Age=3600\r\n"); return true; }
if (std.mem.eql(u8, path, "/acct")) { if (std.mem.indexOf(u8, ckb, "sid=abc123") != null) try reply(outp, "200 OK", "text/html", "<html><head><title>Account</title></head><body><div id=\"app\"></div><script>document.getElementById('app').textContent='Account dashboard for owner with private orders list'</script></body></html>", "") else try reply(outp, "200 OK", "text/html", "<html><head><title>Login</title></head><body><div id=\"app\"></div><script>document.getElementById('app').innerHTML='<form>Please log in <input type=password name=pw></form>'</script></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/sse") or std.mem.eql(u8, path, "/sseinf")) { try outp.writeAll("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: close\r\n\r\n"); try outp.flush(); var nth: u32 = 1; while (nth <= (if (path.len == 4) @as(u32, 5) else 400)) : (nth += 1) { try outp.print("data: msg{d}\n\n", .{nth}); try outp.flush(); std.Io.sleep(self.iozz, .fromMilliseconds(if (path.len == 4) 20 else 40), .awake) catch {}; } return true; }
if (std.mem.eql(u8, path, "/ws") or std.mem.eql(u8, path, "/wsinf")) { const GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"; var cat: [128]u8 = undefined; @memcpy(cat[0..wkb.len], wkb); @memcpy(cat[wkb.len .. wkb.len + GUID.len], GUID); var dig: [20]u8 = undefined; std.crypto.hash.Sha1.hash(cat[0 .. wkb.len + GUID.len], &dig, .{}); var acc: [28]u8 = undefined; _ = std.base64.standard.Encoder.encode(&acc, &dig); try outp.print("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {s}\r\n\r\n", .{&acc}); try outp.flush(); var nth: u32 = 1; while (nth <= (if (path.len == 3) @as(u32, 5) else 400)) : (nth += 1) { var fb: [32]u8 = undefined; const txt = std.fmt.bufPrint(fb[2..], "tick {d}", .{nth}) catch break; fb[0] = 0x81; fb[1] = @intCast(txt.len); try outp.writeAll(fb[0 .. 2 + txt.len]); try outp.flush(); std.Io.sleep(self.iozz, .fromMilliseconds(if (path.len == 3) 30 else 40), .awake) catch {}; } try outp.writeAll(&[_]u8{ 0x88, 0x00 }); try outp.flush(); return true; }
if (std.mem.eql(u8, path, "/wspage")) { const body = try std.fmt.allocPrint(allo, "<html><head><title>WS Page</title></head><body><div id=\"o\">start</div><script>var s=new WebSocket('ws://127.0.0.1:{d}/{s}');s.onmessage=function(e){{document.getElementById('o').textContent=e.data}}</script></body></html>", .{ self.port, if (std.mem.indexOf(u8, rawp, "inf") != null) "wsinf" else "ws" }); defer allo.free(body); try reply(outp, "200 OK", "text/html", body, ""); return true; }
if (std.mem.eql(u8, path, "/ndjson")) { try reply(outp, "200 OK", "application/x-ndjson", "{\"a\":1}\n{\"a\":2}\n", ""); return true; }
if (std.mem.eql(u8, path, "/poll")) { const body = try std.fmt.allocPrint(allo, "{{\"seq\":{d}}}\n", .{self.hits.load(.monotonic)}); defer allo.free(body); try reply(outp, "200 OK", "application/x-ndjson", body, ""); return true; }
if (std.mem.eql(u8, path, "/specapi") or std.mem.eql(u8, path, "/specpost")) { const hd = self.lastz[0..self.lenz]; const post = std.mem.eql(u8, path, "/specpost"); const sigok = std.mem.indexOf(u8, hd, "X-Sig: good123") != null; const bodok = !post or std.mem.indexOf(u8, hd, "\"q\":\"widgets\"") != null; if (!sigok) { try reply(outp, "403 Forbidden", "application/json", "{\"error\":\"signature expired\"}", ""); return true; } if (!bodok) { try reply(outp, "400 Bad Request", "application/json", "{\"error\":\"bad body\"}", ""); return true; } const body = try std.fmt.allocPrint(allo, "{{\"ok\":true,\"query\":\"{s}\",\"items\":[\"alpha\",\"beta\"]}}", .{rawp}); defer allo.free(body); try reply(outp, "200 OK", "application/json", body, ""); return true; }
if (std.mem.eql(u8, path, "/hub")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Hub</title></head><body><p>Hub page with enough visible words to be real content here.</p><a href=\"/p1\">Real item</a><a href=\"/p3\" style=\"display: none\">trap one</a><div style=\"visibility:hidden\"><a href=\"/p9\">trap two</a></div><a href=\"/p8\" rel=\"nofollow\">trap three</a><a class=\"honeypot\" href=\"/p7\">trap four</a></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/hub2")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Hub Two</title></head><body><p>Hub two page with enough visible words to be real content here.</p><a href=\"/p1\">one</a><a href=\"/p2\">two</a><a href=\"/p3\">three</a></body></html>", ""); return true; }
if (std.mem.eql(u8, path, "/spacust")) { try reply(outp, "200 OK", "text/html", "<html><head><title>Acme Widgets</title></head><body><div id=\"root\"></div></body></html>", ""); return true; }
return false; }
